58			const searchToolName = CUSTOM_TOOL_SEARCH_NAME;
59	
60			return <Tag name='toolSearchInstructions'>
61				Use the {searchToolName} tool to search for deferred tools before calling them.<br />
62				<br />
63				<Tag name='mandatory'>
64					You MUST use the {searchToolName} tool to load deferred tools BEFORE calling them directly.<br />
65					This is a BLOCKING REQUIREMENT - deferred tools listed below are NOT available until you load them using the {searchToolName} tool. Once a tool appears in the results, it is immediately available to call.<br />
